// Обработка нажатия на левую клавишу мышки#include "stdafx.h"#include "Queue.h"#include "MnemoWnd.h"#include "QueueWnd.h"//#define DefineMouseL LPBYTE& szQueue,SQueue& q,POINT& point,CQueueWnd* wndint MouseNullL(DefineMouseL)  {  return SkipQueue(szQueue);  }//*****************************************************************************// Программа загружена в режиме нормального оператораint MouseOperatorL(DefineMouseL)  {  QueueM(Queue_Library);  if ( ::PtInRect( &p->mRect, point ) )    {    // Клапан, у которого есть ссылка на регулятор    if ( p->nRegulator != -1 )      {      Queue_Library* s = (Queue_Library*)(q.Dyna.szQueue+p->nRegulator);      wnd->PressNumb( s );      }    else    if ( p->btSendType != QUEUE_NO && p->btSendType != QUEUE_BUTTON )      wnd->PressNumb( p );    else      wnd->SetSelect( &p->mbSelect );    //    return 0;    }  return 1;  }//*****************************************************************************int MouseQueueL(CQueueWnd* wnd,SQueue& q,POINT point)  {  typedef int (*LPFuncMouse)(DefineMouseL);  static  LPFuncMouse gs_funcMouse[TYPE_UNKNOWN+1];  static bool bInit = true;  if ( bInit )    {    bInit=false;    for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )      gs_funcMouse[n] = MouseNullL;    //    gs_funcMouse[TYPE_LIBRARY] = MouseOperatorL;    }  //  LPBYTE szQueue = q.Dyna.szQueue;  if ( szQueue )    {    int n = 0;    unsigned char type;    wnd->mLogic.Begin();    while ( gs_funcMouse[type = *szQueue](szQueue,q,point,wnd) ) n++;    return (type != TYPE_NULL)?n:-1;    }  return -1;  }//*****************************************************************************#define DefineFind LPBYTE& szQueue,SQueue& q,int nNumber, RECT& rcint FindNull(DefineFind)  {  return SkipQueue(szQueue);  }//*****************************************************************************int FindLibr(DefineFind)  {  QueueM(Queue_Library);  if ( p->nNumber == nNumber )    {    rc = p->mRect;    return 0;    }  return 1;  }//*****************************************************************************int FindQueue(SQueue& q,int nNumber,RECT& rc)  {  typedef int (*LPFuncMouse)(DefineFind);  static  LPFuncMouse gs_funcMouse[TYPE_UNKNOWN+1];  static bool bInit = true;  if ( bInit )    {    bInit=false;    for ( int n = 0; n < TYPE_UNKNOWN+1; n++ )      gs_funcMouse[n] = FindNull;    gs_funcMouse[TYPE_LIBRARY] = FindLibr;    }  //  LPBYTE szQueue = q.Dyna.szQueue;  if ( szQueue )    {    int n = 0;    unsigned char type;    while ( gs_funcMouse[type = *szQueue](szQueue,q,nNumber,rc) ) n++;    return (type != TYPE_NULL)?n:-1;    }  return -1;  }//*****************************************************************************